def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    result = sum(values) / len(values)
    return {
        "value": result,
        "trace": {
            "operating_profits": values,
            "count": len(values),
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": None
            }
        }
    }
